import json
import smtplib
# Constants
SMTP_SERVER = "smtp.gmail.com"
SMTP_PORT = 587
EMAIL_ADDRESS = "your.email@gmail.com"
EMAIL_PASSWORD = "your.password"
def task_func(input_data=None, smtp_server=SMTP_SERVER, smtp_port=SMTP_PORT, email_address=EMAIL_ADDRESS, email_password=EMAIL_PASSWORD, smtp=None):
    try:
        data = json.loads(input_data)
    except (json.JSONDecodeError, TypeError):
        return []
    names = []
    recipients = []
    if isinstance(data, list):
        for item in data:
            if 'name' in item and 'email' in item:
                names.append(item['name'])
                recipients.append(item['email'])
    elif isinstance(data, dict):
        if 'name' in data and 'email' in data:
            names.append(data['name'])
            recipients.append(data['email'])
        elif 'recipients' in data:
            for r in data['recipients']:
                if 'name' in r and 'email' in r:
                    names.append(r['name'])
                    recipients.append(r['email'])
    if not names:
        return []
    message = f"Subject: Extracted Names\n\n" + "\n".join(names)
    if smtp is None:
        server = smtplib.SMTP(smtp_server, smtp_port)
        server.starttls()
        server.login(email_address, email_password)
    else:
        server = smtp
    for recipient in recipients:
        server.sendmail(email_address, recipient, message)
    if smtp is None:
        server.quit()
    return names

def task_func(input_data=None, smtp_server=SMTP_SERVER, smtp_port=SMTP_PORT, email_address=EMAIL_ADDRESS, email_password=EMAIL_PASSWORD, smtp=None):
    if input_data is None:
        return []
    try:
        data = json.loads(input_data)
    except json.JSONDecodeError:
        return []
    names = []
    for item in data:
        name = item.get('name', '')
        if name:
            names.append(name)
    if names:
        message = f'Subject: Extracted Names\n\n' + '\n'.join(names)
        if smtp is None:
            server = smtplib.SMTP(smtp_server, smtp_port)
            server.starttls()
            server.login(email_address, email_password)
            server.sendmail(email_address, [email_address], message)
            server.quit()
        else:
            smtp.sendmail(email_address, [email_address], message)
    return names

