import requests
import json
import pandas as pd
import seaborn as sns
import matplotlib.pyplot as plt

HEADERS = {
    'accept': 'application/json'
}

def task_func(url, parameters):
    try:
        response = requests.get(url, params=parameters, headers=HEADERS, timeout=10)
        response.raise_for_status()
        data = response.json()
    except Exception as e:
        raise Exception(f"Failed to retrieve data: {e}")

    if not data:
        raise Exception("Empty data received")

    try:
        df = pd.DataFrame(data)
    except Exception as e:
        raise Exception(f"Invalid data format: {e}")

    if df.empty:
        raise Exception("Empty data received")

    numerical_cols = df.select_dtypes(include=['number']).columns
    if numerical_cols.empty:
        raise Exception("No numerical columns found")

    corr_matrix = df[numerical_cols].corr()

    fig, ax = plt.subplots(figsize=(10, 8))
    sns.heatmap(corr_matrix, annot=True, cmap='coolwarm', ax=ax)
    ax.set_title('Correlation Heatmap')

    return df, ax

def task_func(json_dir_path, word_count):
    word_counter = Counter()
    for filename in os.listdir(json_dir_path):
        if filename.endswith('.json'):
            file_path = os.path.join(json_dir_path, filename)
            with open(file_path, 'r') as f:
                data = json.load(f)
                text = data.get('text', '')
                words = text.split()
                word_counter.update(words)
    return word_counter.most_common(word_count)

